// Digimon Story: Time Stranger game pack — adapter over data/digimon.ts
// (generated by scripts/build-digimon.mjs from data/source/digimon/).
//
// The graph mixes three forward edge kinds: single-input digivolve
// (conditions live on the target: Agent Rank, stat thresholds, items,
// Agent Skills), two-input DNA digivolution (17, personality-gated), and
// lateral mode changes. De-digivolution is free reverse traversal in the
// game; those edges are exported separately (digimonDevolveEdges) and
// deliberately kept OUT of the planner edge set — free up/down movement
// would create cycles in path expansion.

import { DIGIMON_CREATURES, DIGIMON_EDGES } from "../../../data/digimon";
import type { GamePack, TransformEdge } from "../types";

const forward = DIGIMON_EDGES.filter((e) => e.kind !== "dedigivolve");

export const digimonPack: GamePack = {
  gameId: "digimon-time-stranger",
  gameName: "Digimon Story: Time Stranger",
  dataVersion:
    "Field Guide complete incl. DLC through Episode Pack 3 (Mar 2026) · jsuk data snapshot 2026-10-23",
  creatures: DIGIMON_CREATURES.map((c) => ({
    id: c.name,
    name: c.name,
    gameId: "digimon-time-stranger",
  })),
  edges: forward.map(
    (e): TransformEdge => ({
      kind: "digivolve",
      from: e.from,
      to: e.to,
      conditions: e.conditions.map((c) => ({
        kind: c.kind,
        label: c.label,
        value: c.value,
      })),
    }),
  ),
  isBaseCreature: (c) => {
    const found = DIGIMON_CREATURES.find((x) => x.name === c.id);
    return found?.stage === "In-Training I";
  },
  terms: { combine: "digivolve", creature: "Digimon", creatures: "Digimon" },
};

/** Free de-digivolution edges (no requirements), for UI display. */
export const digimonDevolveEdges: TransformEdge[] = DIGIMON_EDGES.filter(
  (e) => e.kind === "dedigivolve",
).map((e) => ({
  kind: "dedigivolve",
  from: e.from,
  to: e.to,
  conditions: [],
}));

/** True when the creature is produced by a two-input DNA digivolution. */
export function isDnaResult(name: string): boolean {
  return DIGIMON_EDGES.some((e) => e.kind === "dna" && e.to === name);
}
